INSERT OVERWRITE TABLE ${schema}.dwd_sr_data_warehouse_nap_diversity_query_keyword_dls_1d
partition (grass_region = ${grass_region}, local_date = ${local_date})
select
    task_data_keyword as keyword
    ,task_data_level1_global_be_category_id as level1_global_be_category_id
    ,task_data_level1_global_be_category as level1_global_be_category
    ,case when completion_data_keep_decision = 'Keep'  then 'Y'
          when  completion_data_keep_decision = 'Not Keep' then 'N'
          else null end  as keep_or_not
from video_bi.trending_page_trending_query_marking_result
where grass_date = (select max(grass_date) from video_bi.trending_page_trending_query_marking_result)
and  task_data_grass_region =${grass_region}
group by 1, 2, 3, 4
